function projectTargets(){if(!host.value)return;const r=host.value.getBoundingClientRect();const point=(v:THREE.Vector3)=>{const p=v.project(camera);return {x:(p.x+1)/2*r.width,y:(1-p.y)/2*r.height,visible:p.z<1&&p.z>-1&&Math.abs(p.x)<.94&&Math.abs(p.y)<.88};};helmPoint.value=point(tiller.localToWorld(new THREE.Vector3(1.04,.1,.05)));drumPoint.value=point(boat.localToWorld(new THREE.Vector3(2.1,.96,.18)));if(basketTarget.value&&props.mode==='collect'){const p=point(new THREE.Vector3(4.7,.85,.2));basketTarget.value.style.left=`${p.x}px`;basketTarget.value.style.top=`${p.y}px`;}targets.value=getHotspots().map(t=>{const p=t.p.project(camera);return{id:t.id,label:t.label,x:(p.x+1)/2*r.width,y:(1-p.y)/2*r.height,visible:p.z<1&&p.z>-1&&Math.abs(p.x)<.93&&Math.abs(p.y)<.85&&hotspotInSafeArea(props.mode,(p.x+1)/2*r.width,(1-p.y)/2*r.height,r.height)};});}
function onPointerDown(e:PointerEvent){down={x:e.clientX,y:e.clientY};if(controls.enableRotate){cameraTo=undefined;lookTo=undefined;}}
function onPointerUp(e:PointerEvent){if(!down||Math.hypot(e.clientX-down.x,e.clientY-down.y)>6)return;down=undefined;if(props.perspective==='shore'){op('inspect',{part:'shore'});return;}if(props.mode==='helm'){notice.value='握住缠绳的舵柄，左右拖动试试。';return;}if(!renderer)return;const r=renderer.domElement.getBoundingClientRect();cursor.set((e.clientX-r.left)/r.width*2-1,-(e.clientY-r.top)/r.height*2+1);raycaster.setFromCamera(cursor,camera);const hit=raycaster.intersectObjects(rayTargets,true).find(h=>h.object.visible);if(!hit)return;const part=hit.object.userData.part;if(part==='drum'&&props.mode==='drum')soundDrum();else if(part==='bucket'&&props.mode==='fire')waterFire();else if(['inspect','river'].includes(props.mode))op('inspect',{part});}
function keyboard(e:KeyboardEvent){if((e.target as HTMLElement).matches('button,input,select,textarea'))return;if(props.perspective==='shore')return;if(props.mode==='return'&&['ArrowLeft','ArrowRight','Enter'].includes(e.key)){e.preventDefault();if(e.key==='Enter')confirmReturn();else returnPreview(returnHeading.value+(e.key==='ArrowRight'?15:-15));return;}if(e.key===' '&&props.mode==='drum'){e.preventDefault();soundDrum();return;}if(props.mode==='helm'&&['ArrowLeft','ArrowRight'].includes(e.key)){e.preventDefault();headingPreview(preview.value+(e.key==='ArrowRight'?30:-30));return;}if(props.mode==='helm'&&e.key==='Enter'){confirmHelm();return;}if(props.mode==='collect'&&e.key==='Enter'){if(selected.value)collect(selected.value);else if(remaining.value[0])selected.value=remaining.value[0].id;return;}if(controls.enableRotate&&['ArrowLeft','ArrowRight','ArrowUp','ArrowDown'].includes(e.key)){e.preventDefault();cameraTo=undefined;const s=new THREE.Spherical().setFromVector3(camera.position.clone().sub(controls.target));if(e.key==='ArrowLeft')s.theta+=.12;if(e.key==='ArrowRight')s.theta-=.12;if(e.key==='ArrowUp')s.phi=Math.max(.22,s.phi-.08);if(e.key==='ArrowDown')s.phi=Math.min(Math.PI*.46,s.phi+.08);camera.position.copy(controls.target).add(new THREE.Vector3().setFromSpherical(s));}}
function animate(time:number){if(disposed||fault.value)return;const dt=Math.min(.05,(time-last)/1000||.016);last=time;if(!epoch)epoch=time;elapsed=(time-epoch)/1000;frame=requestAnimationFrame(animate);if(!props.reducedMotion){water.material.uniforms.time!.value=elapsed;mist.children.forEach((m,i)=>{m.position.x=Number(m.userData.startX)+Math.sin(elapsed*.035+i)*3;});boat.position.y=Math.sin(elapsed*.7)*.025;boat.rotation.z=Math.sin(elapsed*.43)*.005;lamp.intensity=11+Math.sin(elapsed*4.4)*.5;flame.children.forEach((c,i)=>{if(c instanceof THREE.Mesh)c.scale.y=.9+Math.sin(elapsed*7+i)*.18;});}if(props.reducedMotion){boat.position.y=0;boat.rotation.z=0;water.material.uniforms.time!.value=0;}if(cameraTo&&lookTo){const progress=shotProgress(elapsed,shotStarted);camera.position.lerpVectors(cameraFrom,cameraTo,progress);controls.target.lerpVectors(lookFrom,lookTo,progress);camera.fov=fovFrom+(fovTo-fovFrom)*progress;camera.updateProjectionMatrix();if(progress>=1){cameraTo=undefined;lookTo=undefined;}}
 if(turnFrom!==turnTo){const p=props.reducedMotion?1:Math.min(1,(elapsed-turnStart)/4.6);fleet.forEach((b,i)=>b.rotation.y=fleetHeading(turnFrom,turnTo,p,i)*Math.PI/180);currentHeading=fleetHeading(turnFrom,turnTo,p,0);ropeRoot.visible=props.perspective==='ship'&&p>=1;if(p>=1){turnFrom=turnTo;currentHeading=turnTo;turning.value=false;ropeRoot.visible=props.perspective==='ship';}}else fleet.forEach(b=>b.rotation.y=currentHeading*Math.PI/180);ghost.rotation.y=(props.mode==='return'?returnHeading.value:preview.value)*Math.PI/180;ghost.visible=props.perspective==='ship'&&['helm','return'].includes(props.mode);shoreFleet.children.forEach((b,i)=>b.rotation.y=fleet[i]!.rotation.y);drum.scale.y=drumPulse.value?.94:1;drumSticks.forEach((stick,i)=>{const age=elapsed-drumStrikeAt-i*.045;stick.rotation.x=age>=0&&age<.36?.15*Math.sin(age/.36*Math.PI):0;});tiller.rotation.y=(preview.value-currentHeading)*Math.PI/180*.42;collectionDisplay.children.forEach(g=>{if(g.userData.bundleId){const arrows=g.getObjectByName('take-arrows');if(arrows)arrows.position.y=selected.value===g.userData.bundleId?.32:0;}});advanceBatches();animateVolley();animateWater();animateScout();controls.update();projectTargets();updateWaterContact();renderer!.render(scene,camera);}
function error(message:string){cancelMotion();if(fault.value)return;fault.value='江面未能展开。此设备暂不能绘制三维场景，请重新加载或更换支持 WebGL 的浏览器。';cancelAnimationFrame(frame);emit('error',message);}
function resize(){if(!host.value||!renderer)return;const{width,height}=host.value.getBoundingClientRect();if(!width||!height)return;renderer.setSize(width,height,false);renderer.getDrawingBufferSize(water.material.uniforms.viewport!.value);camera.aspect=width/height;camera.updateProjectionMatrix();}
watch(()=>props.backdrop,loadWaterPlate);
watch(()=>[props.material,props.layout],()=>rebuildFittings());
watch(()=>[props.first,props.second],(next,previous)=>{
 collected.value=[];selected.value='';
 if(props.reducedMotion||props.perspective==='shore'||props.mode==='collect'||next[0]!<previous[0]!||next[1]!<previous[1]!){cancelMotion();rebuildArrows();return;}
 if(next[0]!>previous[0]!)pendingBatches.push({side:'right',amount:next[0]!,started:null});
 if(next[1]!>previous[1]!)pendingBatches.push({side:'left',amount:next[1]!,started:null});
 setMotion(pendingBatches.length>0||turning.value);rebuildArrows();
});
watch(()=>props.mode,(mode,previous)=>{notice.value='';selected.value='';if(!['helm','river','fire'].includes(mode)){cancelMotion();rebuildArrows();}if(mode==='collect'&&previous!=='collect'){collected.value=[];rebuildArrows();}syncEnvironment();setView();});
watch(()=>[props.weather,props.fire],syncEnvironment);watch(()=>props.scoutApproaching,visible=>{scoutStarted=visible&&!props.reducedMotion?elapsed:null;syncEnvironment();});
watch(()=>[props.perspective,props.enemyVisible],()=>{if(props.perspective==='shore'){cancelMotion();rebuildArrows();}syncEnvironment();setView();});
watch(()=>props.targetHeading,v=>{if(!boat)return;if(props.reducedMotion||props.perspective==='shore'){cancelMotion();rebuildArrows();return;}turnFrom=currentHeading;turnTo=v;turnStart=elapsed;preview.value=v;turning.value=turnFrom!==turnTo;setMotion(turning.value||pendingBatches.length>0);setView();});
