onMounted(()=>{try{renderer=new THREE.WebGLRenderer({antialias:true,alpha:true,powerPreference:'high-performance'});renderer.localClippingEnabled=true;renderer.setPixelRatio(Math.min(devicePixelRatio,1.6));renderer.outputColorSpace=THREE.SRGBColorSpace;renderer.toneMapping=THREE.ACESFilmicToneMapping;renderer.toneMappingExposure=1;host.value!.prepend(renderer.domElement);renderer.domElement.setAttribute('aria-hidden','true');renderer.domElement.addEventListener('webglcontextlost',lost);renderer.domElement.addEventListener('pointerdown',onPointerDown);renderer.domElement.addEventListener('pointerup',onPointerUp);buildScene();preview.value=props.targetHeading;currentHeading=props.targetHeading;observer=new ResizeObserver(resize);observer.observe(host.value!);resize();frame=requestAnimationFrame(animate);setMotion(false,true);emit('ready');}catch(e){error(e instanceof Error?e.message:'WebGL initialization failed');}});
