</script>
<template>
 <div ref="host" class="scene-stage" :class="`scene-stage--${mode}`" tabindex="0" role="region" :aria-label="['inspect','place'].includes(mode)?'船只检视。拖动或用方向键转动看船，滚轮近看。':'江面情境。根据当前物件上的提示操作。'" @keydown="keyboard" @pointermove.capture="moveBundlePointer" @pointerup.capture="finishBundlePointer" @pointercancel="cancelBundlePointer">
  <img v-if="mode==='collect'" class="scene-stage__collection-backdrop" :src="dawnBackdrop" alt="" aria-hidden="true" />
  <div class="scene-stage__vignette" aria-hidden="true"></div>
  <div v-if="fault" class="scene-stage__fault" role="alert"><span>江面暂未展开</span><p>{{fault}}</p><small>当前操作尚未完成，故事不会假装已经转舷或收箭。</small></div>
  <template v-else>
   <div v-if="!['inspect','place'].includes(mode)" class="scene-stage__horizon" aria-hidden="true"><i></i><span>{{perspective==='shore'?'北岸 · 水寨瞭望':mode==='collect'?'归岸 · 晨江':weather==='clear'?'水寨灯火清楚可辨':'江心 · 对岸水寨'}}</span></div>
   <template v-for="target in targets" :key="target.id"><button v-if="target.visible" class="scene-stage__target" :class="{'is-selected':selected===target.id.slice(7),'is-bundle':target.id.startsWith('bundle:')}" :style="{left:`${target.x}px`,top:`${target.y}px`}" :disabled="busy" :aria-label="target.label" :draggable="false" @pointerdown.stop="beginBundlePointer($event,target.id)" @dragstart.prevent @lostpointercapture="cancelBundlePointer" @click="chooseTarget(target.id)"><i></i><span>{{target.label}}</span></button></template>
   <button v-if="mode==='helm'&&perspective==='ship'&&helmPoint.visible&&!turning" class="scene-stage__tiller-grip" :style="{left:`${helmPoint.x}px`,top:`${helmPoint.y}px`}" :disabled="busy" aria-label="握住舵柄左右拖动，或用下方航向滑杆" @pointerdown.stop="beginHelm" @pointermove.stop="moveHelm" @pointerup.stop="endHelm" @pointercancel="endHelm" @lostpointercapture="endHelm"><i></i><span>握舵 · 左右拖动</span></button>
   <div v-if="mode==='helm'&&perspective==='ship'" class="scene-stage__helm" @pointerdown.stop><span class="scene-stage__eyebrow">{{turning?'各船正在调头':'定好航向，再传令'}}</span><div class="scene-stage__heading"><span>右舷朝岸</span><span>左舷朝岸</span></div><input aria-label="拖船舵预览转向，左右方向键也可调整" type="range" min="0" max="180" step="15" :value="preview" :disabled="busy||turning" @input="headingPreview(Number(($event.target as HTMLInputElement).value))" /><p>{{previewSide==='left'?'左舷':'右舷'}}迎着水寨</p><div class="scene-stage__actions"><button :disabled="busy||turning" @click="headingPreview(previewSide==='right'?180:0)">转向另一舷</button><button class="scene-stage__primary" :disabled="busy||turning" @click="confirmHelm">传令转舷</button></div></div>
   <div v-if="mode==='return'&&perspective==='ship'" class="scene-stage__helm" @pointerdown.stop><span class="scene-stage__eyebrow">韩伯的船舵 · 回南岸</span><div class="scene-stage__heading"><span>向来路收船</span><span>避开水寨</span></div><input aria-label="预览回南岸的航向，左右方向键也可调整" type="range" min="45" max="135" step="15" :value="returnHeading" :disabled="busy" @input="returnPreview(Number(($event.target as HTMLInputElement).value))" /><p>虚线船影指向返航航道</p><button class="scene-stage__primary" :disabled="busy" @click="confirmReturn">传令返航</button></div>
   <div v-if="perspective==='shore'&&visibility.showFleet" class="scene-stage__observation"><span>岸上瞭望</span><i>·</i><span>{{weather==='clear'?'看得到来船，船内仍不清楚':'雾中只辨船影'}}</span></div>
   <div v-if="mode==='drum'&&perspective==='ship'" class="scene-stage__drum" @pointerdown.stop><button class="scene-stage__drum-face" :class="{'is-struck':drumPulse}" :disabled="busy" aria-label="试敲一下军鼓，空格键也可试敲" @click="soundDrum"><span>敲一下</span><small>也可按空格</small></button><button class="scene-stage__primary" :disabled="busy" @click="op('drum',{action:'command'})">传令各船齐鼓</button></div>
