   <button v-if="mode==='drum'&&perspective==='ship'&&drumPoint.visible" class="scene-stage__drum-hit" :class="{'is-struck':drumPulse}" :style="{left:`${drumPoint.x}px`,top:`${drumPoint.y}px`}" :disabled="busy" aria-label="敲击甲板上的军鼓" @click.stop="soundDrum"><span>击鼓</span></button>
   <button ref="basketTarget" v-if="mode==='collect'&&perspective==='ship'&&bundles.length>0" class="scene-stage__basket" :class="{'is-ready':selected}" :disabled="busy||remaining.length===0" @click="collect(selected)" @dragover="overBasket" @drop="dropIntoBasket"><span class="scene-stage__stored" aria-hidden="true"><i v-for="n in collected.length" :key="n" :style="{left:`${22+n*18}px`,transform:`rotate(${(n-3)*5}deg)`}"></i></span><span v-if="!collected.length" class="scene-stage__basket-icon" aria-hidden="true">╲╱</span><strong>放进竹筐</strong><span>{{remaining.length===0?'收箭已毕':selected?'放下手中箭束':'把箭束拖到这里'}}</span><small>{{collected.length}} / {{bundles.length}} 处已入筐</small></button>
   <p v-if="mode==='collect'&&bundles.length===0" class="scene-stage__notice">这一趟没带回箭。回营再议。</p>
   <div v-if="mode==='fire'&&fire==='hit'&&perspective==='ship'" class="scene-stage__fire" @pointerdown.stop><button class="scene-stage__primary" :disabled="busy" @click="waterFire">拿起脚边水桶 · 浇在外侧火处</button></div>
   <div v-if="perspective==='ship'&&['inspect','place'].includes(mode)" class="scene-stage__observation"><span>拖动看船</span><i>·</i><span>方向键环视</span><i>·</i><span>滚轮近看</span></div>
   <p v-if="notice" class="scene-stage__notice" role="status" aria-live="polite">{{notice}}</p>
  </template>
 </div>
</template>
